// Entrada: resposta do GET no Supabase (o n8n ja quebrou o array em itens).
// Saida: 1 item por lead PROCESSAVEL.
// Lead SEM TELEFONE e pulado com log — sem telefone nao da pra procurar nem
// criar contato no Bitrix, e quebrar aqui travaria os outros leads do lote.
// (Ele vai continuar aparecendo em todo ciclo ate ganhar telefone ou
// bitrix_id na mao — o log existe pra esse caso nao ficar invisivel.)
const out = [];
for (const item of $input.all()) {
  const l = item.json || {};
  if (!l.id) continue; // resposta vazia do Supabase: nenhum lead pendente
  const digits = String(l.phone || '').replace(/\D/g, '');
  if (!digits) {
    console.log('[qs-wa-to-bitrix] lead ' + l.id + ' PULADO: sem telefone (' + (l.full_name || 'sem nome') + ')');
    continue;
  }
  out.push({ json: {
    qs_id: String(l.id),
    full_name: String(l.full_name || ('WhatsApp ' + digits.slice(-8))),
    phone: String(l.phone),
    phone_digits: digits,
    email: String(l.email || '')
  } });
}
if (!out.length) console.log('[qs-wa-to-bitrix] nenhum lead pendente neste ciclo.');
return out;

// Junta a resposta do findbycomm com o lead correspondente (itemMatching).
// Achou contato com esse telefone -> contact_id = o primeiro ID achado.
// Nao achou (ou o findbycomm falhou so pra este item) -> contact_id = null
// e o fluxo cria um contato novo. Um lead com erro NAO derruba os demais.
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const r = items[i].json || {};
  let lead = {};
  try { lead = $('Preparar leads').itemMatching(i).json; } catch (e) { /* pareamento perdido */ }
  if (!lead.qs_id) {
    console.log('[qs-wa-to-bitrix] item ' + i + ' sem par no Preparar leads — pulado');
    continue;
  }
  if (r.error) {
    console.log('[qs-wa-to-bitrix] findbycomm falhou pro lead ' + lead.qs_id + ' (' + (r.error_description || JSON.stringify(r.error)) + ') — segue e cria contato novo');
  }
  let contactId = null;
  const achados = r.result && r.result.CONTACT;
  if (Array.isArray(achados) && achados.length) contactId = String(achados[0]);
  out.push({ json: Object.assign({}, lead, { contact_id: contactId }) });
}
return out;

// Le o resultado do crm.contact.add. O Bitrix responde HTTP 200 com
// {"error":...} quando recusa, e o onError do no anterior deixa o item de
// erro passar — entao a checagem tem que ser AQUI. Falhou pra um lead?
// Esse lead e pulado (fica com bitrix_id null e volta no proximo ciclo);
// os demais seguem.
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const r = items[i].json || {};
  let lead = {};
  try { lead = $('Decidir contato').itemMatching(i).json; } catch (e) { /* pareamento perdido */ }
  if (!lead.qs_id) continue;
  if (r.error || !r.result) {
    console.log('[qs-wa-to-bitrix] contact.add FALHOU pro lead ' + lead.qs_id + ': ' + (r.error_description || JSON.stringify(r.error) || 'resposta vazia') + ' — fica pro proximo ciclo');
    continue;
  }
  out.push({ json: Object.assign({}, lead, { contact_id: String(r.result) }) });
}
return out;

// Le o resultado do crm.deal.add e monta o PATCH de volta pro Supabase.
// r.result = ID do negocio criado -> vira o bitrix_id do lead no QS.
// Falhou pra um lead? Loga e pula (volta no proximo ciclo); os demais seguem.
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const r = items[i].json || {};
  let lead = {};
  try { lead = $('Decidir contato').itemMatching(i).json; } catch (e) { /* pareamento perdido */ }
  if (!lead.qs_id) {
    console.log('[qs-wa-to-bitrix] deal criado mas SEM par pro item ' + i + ' — bitrix_id nao sera gravado; confira a execucao');
    continue;
  }
  if (r.error || !r.result) {
    console.log('[qs-wa-to-bitrix] deal.add FALHOU pro lead ' + lead.qs_id + ': ' + (r.error_description || JSON.stringify(r.error) || 'resposta vazia') + ' — fica pro proximo ciclo');
    continue;
  }
  out.push({ json: { qs_id: lead.qs_id, bitrix_id: String(r.result) } });
}
if (!out.length) console.log('[qs-wa-to-bitrix] nenhum negocio criado neste ciclo.');
return out;

// O PATCH acima segue em frente mesmo com erro (pra nao perder os PATCHes
// dos outros leads do lote). Mas PATCH perdido = lead reprocessado no
// proximo ciclo = NEGOCIO DUPLICADO no Bitrix. Entao qualquer falha aqui
// tem que ficar VERMELHA na lista de execucoes.
const falhas = $input.all().filter(function (i) { return i.json && i.json.error; });
if (falhas.length) {
  throw new Error(falhas.length + ' PATCH(es) de bitrix_id FALHARAM no Supabase — esses leads serao reprocessados e vao DUPLICAR negocio no Bitrix no proximo ciclo. Conserte ja (ou desative o workflow enquanto investiga).');
}
return [{ json: { ok: true, gravados: $input.all().length } }];
